source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # The palette is a short run of identical rows or columns.
    candidates = []
    for r in range(h - 1):
        if grid[r] == grid[r + 1] and any(grid[r]):
            end = r + 2
            while end < h and grid[end] == grid[r]:
                end += 1
            vals = [v for v in grid[r] if v]
            if len(vals) >= 2:
                candidates.append((len(vals), (r, 0, end, w), vals))
    for c in range(w - 1):
        col = [grid[r][c] for r in range(h)]
        col2 = [grid[r][c + 1] for r in range(h)]
        if col == col2 and any(col):
            end = c + 2
            while end < w and all(grid[r][end] == col[r] for r in range(h)):
                end += 1
            vals = [v for v in col if v]
            if len(vals) >= 2:
                candidates.append((len(vals), (0, c, h, end), vals))
    if not candidates:
        return [row[:] for row in grid]
    _, (r0, c0, r1, c1), palette = max(candidates, key=lambda x: x[0])
    out = [row[:] for row in grid]
    for r in range(r0, r1):
        for c in range(c0, c1):
            out[r][c] = 0
    # Find the colored motif components outside the palette marker.
    blocked = {(r, c) for r in range(r0, r1) for c in range(c0, c1)}
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in blocked or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in blocked and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx)); stack.append((yy, xx))
            comps.append((color, cells))
    # Motif copies are identical shapes in palette colors; use the first copy as template.
    by_color = {}
    for color, cells in comps:
        by_color.setdefault(color, []).append(cells)
    copies = [(color, cells) for color, cells in comps if color in palette]
    if not copies:
        return out
    color, cells = min(copies, key=lambda z: min(y for y,x in z[1]))
    miny = min(y for y,x in cells); minx = min(x for y,x in cells)
    shape = {(y-miny, x-minx) for y,x in cells}
    sh = max(y for y,x in shape) + 1
    sw = max(x for y,x in shape) + 1
    # The existing copies determine the vertical anchor; missing palette colors fill the sequence.
    indexed = []
    for col, ccells in copies:
        ys = [y for y,x in ccells]; xs = [x for y,x in ccells]
        top = min(ys); left = min(xs)
        norm = {(y-top, x-left) for y,x in ccells}
        if norm == shape and col in palette:
            indexed.append((palette.index(col), top, left))
    if not indexed:
        return out
    anchor = indexed[0][1] - indexed[0][0] * sh
    left = indexed[0][2]
    for i, col in enumerate(palette):
        top = anchor + i * sh
        for dy, dx in shape:
            y, x = top + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = col
    return out
'''
